1	"use client";
2	
3	/**
4	 * Ctrl+K overlay shell; the domain layer supplies the groups.
5	 *
6	 * Owner A — design system. Knows nothing about commands: it filters the groups
7	 * it is handed, keeps a single flat active index across group boundaries (so
8	 * ArrowDown walks from the last item of one group into the first of the next),
9	 * and reports the chosen id. Registering shortcuts is `useCommandPalette`'s job.
10	 */
11	import { useMemo, useState } from "react";
12	import type { KeyboardEvent, ReactElement } from "react";
13	import { cn } from "@/lib/cn";
14	import { isNavKey, matchesQuery, moveActiveIndex } from "./_lib/list-navigation";
15	import { CONTROL_BORDER, OVERLAY, SURFACE } from "./_lib/tokens";
16	import { useDismissableLayer, useScrollLock } from "./_lib/use-dismissable-layer";
17	
18	export type CommandGroup = { heading: string; items: readonly CommandItemSpec[] };
19	
20	export type CommandItemSpec = { id: string; label: string; hint?: string; shortcut?: string };
21	
22	export type CommandPaletteProps = { open: boolean; groups: readonly CommandGroup[]; placeholder?: string; onClose: () => void; onSelect: (id: string) => void };
23	
24	type FlatRow = { item: CommandItemSpec; heading: string; index: number };
25	
26	/**
27	 * Filter the groups and number the surviving items in render order. The flat
28	 * index is what makes arrow navigation continuous across headings.
29	 */
30	export function flattenGroups(
31	  groups: readonly CommandGroup[],
32	  query: string,
33	): { rows: FlatRow[]; sections: { heading: string; rows: FlatRow[] }[] } {
34	  const rows: FlatRow[] = [];
35	  const sections: { heading: string; rows: FlatRow[] }[] = [];
36	
37	  for (const group of groups) {
38	    const kept: FlatRow[] = [];
