/**
 * Re-indexes one subject for a `search.reindex_requested` event, whatever
 * tool asked for it (an ops "reindex this item" action, a cleanup job). A
 * subject that no longer exists or has been archived is left out of the
 * index rather than indexed as live (ADR 0007, rule 7).
 */
async function reindexSubject(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  switch (subjectKind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, subjectId as Issue["id"]);
      if (issue && isLive(issue)) {
        await indexIssue(orgId, issue);
      } else {
        await removeFromIndex(orgId, "issue", subjectId);
      }
      return;
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as Comment["id"],
      );
      const issue =
        comment && isLive(comment)
          ? await issueRepo.findIssueById(orgId, comment.issueId)
          : null;
      if (comment && isLive(comment) && issue) {
        await indexComment(orgId, comment, issue.projectId);
      } else {
        await removeFromIndex(orgId, "comment", subjectId);
      }
      return;
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as Project["id"],
      );
      if (project && isLive(project)) {
        await indexProject(orgId, project);
      } else {
        await removeFromIndex(orgId, "project", subjectId);
      }
      return;
    }
  }
}

