13	import * as commentRepo from "@/server/repositories/comment-repository";
14	import * as issueRepo from "@/server/repositories/issue-repository";
15	import * as orgRepo from "@/server/repositories/organization-repository";
16	import * as projectRepo from "@/server/repositories/project-repository";
17	import * as searchRepo from "@/server/repositories/search-repository";
18	import { orgResource } from "./_support";
19	import type { SearchQueryInput } from "@/schemas/search";
20	import type { SearchSubjectKind } from "@/server/repositories/search-repository";
21	import type { Comment } from "@/types/comment";
22	import type { OrgId, Page, ProjectId } from "@/types/common";
23	import type { Unsubscribe } from "@/types/event";
24	import type { Issue } from "@/types/issue";
25	import type { Actor } from "@/types/member";
26	import type { Project } from "@/types/project";
27	
28	export type SearchHit = {
29	  kind: SearchSubjectKind;
30	  id: string;
31	  title: string;
32	  snippet: string;
33	  href: string;
34	};
35	
36	/** Characters of surrounding context kept on either side of a match. */
37	const SNIPPET_RADIUS = 60;
38	
39	/** Token bucket protecting the index from query bursts. */
40	const SEARCH_QUERY_BUCKET = "search:query";
41	
42	/**
43	 * Runs a query against the denormalised index. Field-scoped syntax
44	 * (`kind:`/`in:`/`project:`) is an `advanced_search` feature: on plans without
45	 * it a colon is just a character (ADR 0007, rule 3) and only issues are ever
46	 * searched (rule 4). The field tokens, when they apply, are extracted here
47	 * with the same parser the dialog uses for its hint line (rule 5), so this is
48	 * the one place a query is turned into index filters — entry points above
49	 * this pass the query and requested kinds through unmodified.
50	 */
51	export async function search(
52	  actor: Actor,
53	  input: SearchQueryInput,
54	): Promise<Page<SearchHit>> {
55	  assertOrgScope(actor, input.orgId);
56	  assertCan(actor, "issue:read", orgResource(input.orgId));
57	
58	  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
59	  if (!verdict.allowed) {
60	    throw new Error(
61	      `Search rate limit reached; try again after ${verdict.resetAt}`,
62	    );
63	  }
64	
65	  const org = await orgRepo.findOrgById(input.orgId);
66	  const advanced = isEnabled("advanced_search", {
67	    orgId: input.orgId,
68	    userId: actor.userId,
69	    plan: org?.plan ?? "free",
70	    role: actor.role,
71	    overrides: org?.settings.enabledFlagOverrides,
72	  });
73	
74	  const tokens = advanced
75	    ? extractSearchTokens(input.q)
76	    : { text: normaliseQuery(input.q), kinds: [], projectId: null as ProjectId | null };
77	
78	  const kinds = !advanced
79	    ? (["issue"] as const)
80	    : tokens.kinds.length > 0
81	      ? tokens.kinds
82	      : input.kinds;
83	  const projectId = tokens.projectId ?? input.projectId;
84	
85	  const page = await searchRepo.searchDocuments({
86	    ...input,
87	    q: tokens.text,
88	    kinds,
89	    projectId,
90	  });
91	
92	  return {
93	    items: page.items.map((row) => ({
94	      kind: row.subjectKind,
95	      id: row.subjectId,
96	      title: row.content.split("\n")[0] ?? row.subjectId,
97	      snippet: snippetAround(row.content, tokens.text),
98	      href: hrefFor(row.subjectKind, row.subjectId),
99	    })),
100	    nextCursor: page.nextCursor,
101	    total: page.total,
102	  };
103	}
104	
105	/** Free-text queries are matched literally; only whitespace is tidied up. */
106	function normaliseQuery(raw: string): string {
107	  return raw.trim().replace(/\s+/g, " ");
108	}
109	
110	export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
111	  await searchRepo.upsertSearchDocument(
112	    orgId,
113	    "issue",
114	    issue.id,
115	    [issue.title, issue.description ?? ""].join("\n"),
116	    issue.projectId,
117	  );
118	}
119	
120	/**
121	 * A comment carries the project id of the issue it was posted on (ADR 0007,
122	 * rule 6), so `project:` scoping finds comments as well as issues.
123	 */
124	export async function indexComment(
125	  orgId: OrgId,
126	  comment: Comment,
127	  projectId: ProjectId,
128	): Promise<void> {
129	  await searchRepo.upsertSearchDocument(
130	    orgId,
131	    "comment",
132	    comment.id,
133	    comment.body,
134	    projectId,
135	  );
136	}
