138	export async function indexProject(
139	  orgId: OrgId,
140	  project: Project,
141	): Promise<void> {
142	  await searchRepo.upsertSearchDocument(
143	    orgId,
144	    "project",
145	    project.id,
146	    [project.name, project.description ?? ""].join("\n"),
147	    project.id,
148	  );
149	}
