151	export async function removeFromIndex(
152	  orgId: OrgId,
153	  subjectKind: SearchSubjectKind,
154	  subjectId: string,
155	): Promise<void> {
156	  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
157	}
