159	/**
160	 * Keeps the index in step with writes. Every handler re-reads the row rather
161	 * than trusting the event payload, so a partially-applied write can never be
162	 * indexed as if it had succeeded.
163	 */
164	export function registerSearchListeners(): Unsubscribe {
165	  const offs: Unsubscribe[] = [
166	    subscribe("issue.created", async (payload) => {
167	      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
168	      if (issue) await indexIssue(payload.orgId, issue);
169	    }),
170	    subscribe("issue.updated", async (payload) => {
171	      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
172	      if (issue) await indexIssue(payload.orgId, issue);
173	    }),
174	    subscribe("issue.archived", async (payload) => {
175	      await removeFromIndex(payload.orgId, "issue", payload.issueId);
176	    }),
177	    subscribe("comment.created", async (payload) => {
178	      const comment = await commentRepo.findCommentById(
179	        payload.orgId,
180	        payload.commentId,
181	      );
182	      if (!comment) return;
183	      const issue = await issueRepo.findIssueById(payload.orgId, comment.issueId);
184	      if (issue) await indexComment(payload.orgId, comment, issue.projectId);
185	    }),
186	    subscribe("comment.deleted", async (payload) => {
187	      await removeFromIndex(payload.orgId, "comment", payload.commentId);
188	    }),
189	    subscribe("project.created", async (payload) => {
190	      const project = await projectRepo.findProjectById(
191	        payload.orgId,
192	        payload.projectId,
193	      );
194	      if (project) await indexProject(payload.orgId, project);
195	    }),
196	    subscribe("project.archived", async (payload) => {
197	      await removeFromIndex(payload.orgId, "project", payload.projectId);
198	    }),
199	    subscribe("search.reindex_requested", async (payload) => {
200	      await reindexSubject(payload.orgId, payload.subjectKind, payload.subjectId);
201	    }),
202	  ];
203	
204	  return () => {
205	    for (const off of offs) off();
206	  };
207	}
208	
209	/**
210	 * Re-indexes one subject for a `search.reindex_requested` event, whatever
211	 * tool asked for it (an ops "reindex this item" action, a cleanup job). A
212	 * subject that no longer exists or has been archived is left out of the
213	 * index rather than indexed as live (ADR 0007, rule 7).
214	 */
215	async function reindexSubject(
216	  orgId: OrgId,
217	  subjectKind: SearchSubjectKind,
218	  subjectId: string,
219	): Promise<void> {
220	  switch (subjectKind) {
221	    case "issue": {
222	      const issue = await issueRepo.findIssueById(orgId, subjectId as Issue["id"]);
223	      if (issue && isLive(issue)) {
224	        await indexIssue(orgId, issue);
225	      } else {
226	        await removeFromIndex(orgId, "issue", subjectId);
227	      }
228	      return;
229	    }
230	    case "comment": {
231	      const comment = await commentRepo.findCommentById(
232	        orgId,
233	        subjectId as Comment["id"],
234	      );
235	      const issue =
236	        comment && isLive(comment)
