241	      } else {
242	        await removeFromIndex(orgId, "comment", subjectId);
243	      }
244	      return;
245	    }
246	    case "project": {
247	      const project = await projectRepo.findProjectById(
248	        orgId,
249	        subjectId as Project["id"],
250	      );
251	      if (project && isLive(project)) {
252	        await indexProject(orgId, project);
253	      } else {
254	        await removeFromIndex(orgId, "project", subjectId);
255	      }
256	      return;
257	    }
258	  }
259	}
