import { afterAll, beforeAll, describe, expect, it } from "vitest";

vi_mocks();
function vi_mocks() {}

import { vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("bug reports", () => {
  it("1. colon in query on a plan without advanced_search is not rejected", async () => {
    const t: Tenant = await createTenant("bugstarter", "starter");
    await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Release 2: hotfix" }),
    );
    const hits = await searchService.search(t.actors.member, {
      orgId: t.org.id,
      q: "Release 2: hotfix",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(1);
  });

  it("2. kind: and in: and project: tokens narrow instead of being searched literally", async () => {
    const t: Tenant = await createTenant("bugent", "enterprise");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Deploy pipeline" }),
    );
    await commentService.createComment(t.actors.member, {
      orgId: t.org.id,
      issueId: issue.id,
      body: "this is flaky today",
      parentId: null,
      mentionedUserIds: [],
    });

    const r1 = await searchService.search(t.actors.member, {
      orgId: t.org.id,
      q: "kind:comment flaky",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(r1.total).toBe(1);
    expect(r1.items[0]?.kind).toBe("comment");

    const r2 = await searchService.search(t.actors.member, {
      orgId: t.org.id,
      q: "in:comments flaky",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(r2.total).toBe(1);

    const r3 = await searchService.search(t.actors.member, {
      orgId: t.org.id,
      q: `project:${t.project.id} deploy`,
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(r3.total).toBe(1);
    expect(r3.items[0]?.kind).toBe("issue");
  });

  it("3. project-scoped search returns comments on that project's issues", async () => {
    const t: Tenant = await createTenant("bugproj", "enterprise");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Scoped issue" }),
    );
    await commentService.createComment(t.actors.member, {
      orgId: t.org.id,
      issueId: issue.id,
      body: "UniqueScopedCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });

    const hits = await searchService.search(t.actors.member, {
      orgId: t.org.id,
      q: "UniqueScopedCommentMarker",
      kinds: ["comment"],
      projectId: t.project.id,
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(1);
  });

  it("4. percent and underscore are matched literally", async () => {
    const t: Tenant = await createTenant("bugwild", "enterprise");
